CREATE VIEW `session_read_model` AS select "sessions"."id", "sessions"."source_session_id", "sessions"."project_id", "projects"."name", "projects"."path", "sessions"."parent_id", "sessions"."fork_of", "sessions"."agent_id", "sessions"."source", "sessions"."client_name", "sessions"."client_version", "sessions"."cwd", "sessions"."git_branch", "sessions"."claude_version", "session_stats"."user_turns", "session_stats"."assistant_turns", "session_stats"."tool_calls", "session_stats"."started_at", "session_stats"."ended_at", "session_stats"."duration_ms", "session_stats"."tok_input", "session_stats"."tok_output", "session_stats"."tok_cache_read", "session_stats"."tok_cache_write", "session_stats"."tok_dead_branch", "session_stats"."cost_usd", "session_stats"."updated_at" from "sessions" inner join "projects" on "sessions"."project_id" = "projects"."id" inner join "session_stats" on "sessions"."id" = "session_stats"."session_id";